mapper.update:

UPDATE habit SET status=#{status},current_revision_no=#{currentRevisionNo},ended_at=#{endedAt},

    deleted_at=#{deletedAt},version=version+1,updated_at=#{updatedAt}

WHERE user_id=#{userId} AND id=#{id} AND version=#{version} AND deleted_at IS NULL
